function trackPos(d,x,i){const n=dist(d),p=Math.min(1,x.m/n),l=x.r.lane;if(n===100)return{x:TRACK.L+(TRACK.R-TRACK.L)*p,y:TRACK.Y+rad(l)+x.cosmetic};if(n===200)return stadium(rad(l),200+x.m+(l-1)*3.8*(1-p));if(n===400)return stadium(rad(l),x.m+(l-1)*7.4*(1-p));if(n===800){const z=Math.min(1,x.m/125),pack=distancePackRadius(x);return stadium(pack+(rad(l)-pack)*(1-z),x.m+(l-1)*3.7*(1-z))}return stadium(distancePackRadius(x),x.m)}
function sprintPhase(c,state){const n=dist(c.d),p=state?.p||0;if(c.intro>0)return c.intro<.38?'SET':'START LIST';if(c.photo!=null)return'PHOTO';if(c.runout!=null||c.settle!=null)return'PROVISIONAL';if(n===100)return p<.18?'DRIVE PHASE':p<.58?'ACCELERATION':p<.84?'TOP SPEED':'FINISH';if(n===200)return p<.46?'BEND':p<.61?'TRANSITION':'HOME STRAIGHT';if(n===400)return p<.23?'FIRST BEND':p<.5?'BACK STRAIGHT':p<.76?'FINAL BEND':'HOME STRAIGHT';if(n>=800){const laps=Math.max(2,Math.ceil(n/400)),lead=state?.lead?.m||0,remaining=Math.max(0,n-lead);if(remaining<=200)return'FINAL 200';if(remaining<=400)return'FINAL LAP';const left=Math.ceil(remaining/400);return left<=2?'2 LAPS TO GO':`LAP ${Math.min(laps,Math.floor(lead/400)+1)}/${laps}`}return'LIVE'}
function fitCamera(points,pad=66,minW=400,minH=235){if(!points.length)return[20,18,720,419];let minX=Math.min(...points.map(p=>p.x))-pad,maxX=Math.max(...points.map(p=>p.x))+pad,minY=Math.min(...points.map(p=>p.y))-pad,maxY=Math.max(...points.map(p=>p.y))+pad,w=Math.max(minW,maxX-minX),h=Math.max(minH,maxY-minY);const ar=760/455;if(w/h<ar)w=h*ar;else h=w/ar;w=Math.min(720,w);h=Math.min(419,h);let x=(minX+maxX)/2-w/2,y=(minY+maxY)/2-h/2;x=Math.max(20,Math.min(740-w,x));y=Math.max(18,Math.min(437-h,y));return[x,y,w,h]}
function distanceGroups(c,state){const active=(state?.a||[]).filter(x=>!x.status),n=dist(c.d),speed=(active[0]?.r?.perf&&n)?n/active[0].r.perf:6,gapM=n<=800?4.5:n<=1500?6.5:10,groups=[];for(const x of active){const prev=groups.at(-1)?.at(-1);if(!prev||prev.m-x.m<=gapM){if(groups.length)groups.at(-1).push(x);else groups.push([x])}else groups.push([x])}const lead=active[0],second=active[1],gapS=lead&&second?Math.max(0,(lead.m-second.m)/(speed||1)):0;return{active,groups,gapS,breakaway:gapS>=(n<=800?.65:n<=1500?1:1.8)}}
function distanceCameraTarget(c,state){const n=dist(c.d),g=distanceGroups(c,state),remaining=Math.max(0,n-(state?.lead?.m||0));if(c.intro>0)return[20,18,720,419];let focus=g.active;if(g.breakaway&&remaining>220)focus=g.active.slice(0,Math.min(5,g.active.length));else if(remaining<=400)focus=g.active.slice(0,Math.min(6,g.active.length));const pts=focus.map((x,i)=>trackPos(c.d,x,i));const pad=remaining<=220?48:g.breakaway?60:76,minW=remaining<=220?430:500,minH=remaining<=220?245:285;return fitCamera(pts,pad,minW,minH)}
function cameraTarget(c,state){const n=dist(c.d),p=state?.p||0,lead=state?.lead?.m||0;if(n===100){if(c.intro>0)return[135,270,505,125];const w=p<.18?485:p<.7?420:365,h=p<.18?125:118,x=Math.max(135,Math.min(250,TRACK.L+(TRACK.R-TRACK.L)*(lead/n)-w*.62));return[x,274,w,h]}if(n===200){if(p<.42)return[38,32,684,390];if(p<.68)return[74,126,620,300];return[118,240,548,178]}if(n===400){if(p<.55)return[28,22,704,411];if(p<.78)return[58,86,660,335];return[116,238,548,182]}if(n>=800)return distanceCameraTarget(c,state);return[0,0,760,455]}
